// Erwartet: { objektId, dokumente: [{ name, status }] }
// Status-Vokabular vereinheitlichen: vorhanden | in_pruefung | ausstehend
const MAP = { ok: 'vorhanden', done: 'vorhanden', pruefung: 'in_pruefung', fehlt: 'ausstehend', offen: 'ausstehend' };
const d = $input.first().json;
const dokumente = (d.dokumente ?? []).map((x) => ({
  name: String(x.name ?? '').trim(),
  status: MAP[String(x.status ?? '').toLowerCase()] ?? String(x.status ?? 'ausstehend'),
}));
const vorhanden = dokumente.filter((x) => x.status === 'vorhanden').length;
return [{ json: { objektId: d.objektId, stand: new Date().toISOString(), dokumente, vorhanden, gesamt: dokumente.length } }];
